wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::response_channel;

struct Node;

impl Guest for Node {
    fn run(reply: AgentResponse) -> DeliveryConfirmation {
        // The requires clause (len(text) <= 100000) is the caller's obligation
        // and is not re-checked here; the text is forwarded unchanged.
        let confirmation = response_channel::send(&reply.text);

        // The ensures clauses must hold of every output. If the channel did not
        // confirm delivery, or did not identify the session, there is no valid
        // output to return, so trap instead of returning a violating value.
        // With panic = "abort" this compiles to a wasm trap.
        if !confirmation.delivered {
            panic!("SendReply: channel did not confirm delivery");
        }
        if confirmation.session.trim().is_empty() {
            panic!("SendReply: channel returned no session id");
        }

        confirmation
    }
}

export!(Node);
